using FixIt.Infrastructure.Persistence.Outbox;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;

namespace FixIt.Infrastructure.Persistence.Configurations;

public class OutboxMessageConfiguration : IEntityTypeConfiguration<OutboxMessage>
{
    public const string TableName = "OutboxMessages";

    public void Configure(EntityTypeBuilder<OutboxMessage> builder)
    {
        builder.ToTable(TableName);

        builder.HasKey(m => m.Id);

        // Keys come from the domain event (EventId), never generated by the database
        builder.Property(m => m.Id).IsRequired().ValueGeneratedNever();

        builder.Property(m => m.Type).IsRequired().HasMaxLength(200);

        builder.Property(m => m.Payload).IsRequired().HasColumnType("jsonb");

        builder.Property(m => m.OccurredAt).IsRequired();

        builder.Property(m => m.ProcessedAt);

        builder.Property(m => m.Attempts).IsRequired().HasDefaultValue(0);

        builder.Property(m => m.LastError).HasMaxLength(OutboxMessage.MaxErrorLength);

        // The publisher only scans pending rows; a partial index keeps that cheap as history grows
        builder
            .HasIndex(m => m.OccurredAt)
            .HasFilter("\"ProcessedAt\" IS NULL")
            .HasDatabaseName("IX_OutboxMessages_Pending");
    }
}
